# =============================================================================
# SP Debug Recorder：在前向关键位置记录 tensor 到 /tmp，供事后对比
# =============================================================================

class SPDebugRecorder:
    """
    使用方式：
        # 开启录制（在脚本开头）：
        from onerec_llm.models.qwen3_5.modeling_qwen3_5_sp import SP_DEBUG
        SP_DEBUG.enable(rank=0, out_dir="/tmp/sp_debug")

        # 运行前向 ...

        # 关闭并保存：
        SP_DEBUG.save()

    然后用 tests/test_qwen3_5/test_sp/compare_sp_debug.py 对比两次的结果。
    """
    def __init__(self):
        self._enabled = False
        self._rank = 0
        self._out_dir = "/tmp/sp_debug"
        self._records: dict = {}   # key -> tensor (cpu float32)

    def enable(self, rank: int = 0, out_dir: str = "/tmp/sp_debug"):
        self._enabled = True
        self._rank = rank
        self._out_dir = out_dir
        self._records = {}
        import os
        os.makedirs(out_dir, exist_ok=True)
        print(f"[SPDebugRecorder] enabled, rank={rank}, out_dir={out_dir}", flush=True)

    def disable(self):
        self._enabled = False

    @property
    def enabled(self) -> bool:
        return self._enabled

    def record(self, key: str, tensor: "torch.Tensor"):
        """记录一个 tensor（自动转 cpu float32，避免影响显存）。"""
        if not self._enabled:
            return
        import torch as _torch
        self._records[key] = tensor.detach().cpu().float()

    def save(self):
        """把所有 record 一次性保存到 out_dir/rank{rank}.pt。"""
        if not self._enabled:
            return
        import os, torch as _torch
        path = os.path.join(self._out_dir, f"rank{self._rank}.pt")
        _torch.save(self._records, path)
        print(f"[SPDebugRecorder] saved {len(self._records)} tensors -> {path}", flush=True)
        return path


# 全局单例
SP_DEBUG = SPDebugRecorder()


