_SEQUENCE_PARALLEL_GROUP = None
_SEQUENCE_PARALLEL_GROUP_GLOO = None
_DATA_PARALLEL_GROUP = None

# ---------------------------------------------------------------------------
# all2all 计时辅助：打印每次 all2all 的耗时和数据大小
# 环境变量 SP_A2A_LOG 控制开关：
#   - "0" 或 "off"：关闭日志（生产训练推荐）
#   - "1" 或未设置：默认行为（前 10 步全打印，之后每 100 步一次）
#   - 正整数 N：每 N 步打印一次（覆盖默认频率）
# 仅 global rank 0 打印。
# ---------------------------------------------------------------------------
_SP_A2A_LOG_COUNTER: int = 0   # 全局 all2all 调用次数（所有层共享）
_SP_A2A_LOG_FREQ_INIT: int = 10    # 前 N 次全打印
_SP_A2A_LOG_FREQ_LATER: int = 100  # 之后每隔 N 次打印一次

# ── 解析环境变量 ──────────────────────────────────────────────────────────
_sp_a2a_log_env = os.environ.get("SP_A2A_LOG", "1").lower()
if _sp_a2a_log_env in ("0", "off", "false", "no"):
    _SP_A2A_LOG_ENABLED: bool = False
elif _sp_a2a_log_env in ("1", "on", "true", "yes", ""):
    _SP_A2A_LOG_ENABLED: bool = True
else:
    # 用户指定了数字，作为 freq_later 使用
    _SP_A2A_LOG_ENABLED: bool = True
    _SP_A2A_LOG_FREQ_LATER = int(_sp_a2a_log_env)
    _SP_A2A_LOG_FREQ_INIT = min(_SP_A2A_LOG_FREQ_LATER, 10)


def _timed_all2all(
    spg,
    tensor: "torch.Tensor",
    scatter_idx: int,
    gather_idx: int,
    label: str,
) -> "torch.Tensor":
    """包裹 SeqAllToAll4D，计时并打印 shape / bytes / 耗时（仅 rank 0）。"""
    import time as _time
    global _SP_A2A_LOG_COUNTER

    _SP_A2A_LOG_COUNTER += 1
    cnt = _SP_A2A_LOG_COUNTER

    should_log = (
        _SP_A2A_LOG_ENABLED
        and dist.is_initialized()
        and dist.get_rank() == 0
        and (cnt <= _SP_A2A_LOG_FREQ_INIT or cnt % _SP_A2A_LOG_FREQ_LATER == 0)
    )

    if should_log:
        nbytes = tensor.numel() * tensor.element_size()
        nbytes_mb = nbytes / 1024 / 1024
        shape_in = tuple(tensor.shape)
        _t0 = _time.perf_counter()

    out = SeqAllToAll4D.apply(spg, tensor, scatter_idx, gather_idx)

    if should_log:
        # CUDA 同步，确保计时准确
        if tensor.is_cuda:
            torch.cuda.synchronize()
        elapsed_ms = (_time.perf_counter() - _t0) * 1000
        shape_out = tuple(out.shape)
        print(
            f"[a2a #{cnt}] {label}  "
            f"scatter={scatter_idx}->gather={gather_idx}  "
            f"in={shape_in}  out={shape_out}  "
            f"size={nbytes_mb:.2f} MB  time={elapsed_ms:.2f} ms",
            flush=True,
        )

    return out


def initialize_sequence_parallel(sequence_parallel_size: int):
    """初始化序列并行进程组。
    
    序列并行组：相邻 rank 组成一组，负责拆分同一个序列。
    数据并行组：间隔 sequence_parallel_size 的 rank 一组，处理不同 batch。
    """
    global _SEQUENCE_PARALLEL_GROUP, _SEQUENCE_PARALLEL_GROUP_GLOO, _DATA_PARALLEL_GROUP
    world_size = dist.get_world_size()
    rank = dist.get_rank()
    num_sp_groups = world_size // sequence_parallel_size

    for i in range(num_sp_groups):
        ranks = list(range(i * sequence_parallel_size, (i + 1) * sequence_parallel_size))
        group = dist.new_group(ranks)
        group_gloo = dist.new_group(ranks, backend="gloo")
        if rank in ranks:
            _SEQUENCE_PARALLEL_GROUP = group
            _SEQUENCE_PARALLEL_GROUP_GLOO = group_gloo

    for i in range(sequence_parallel_size):
        ranks = [r for r in range(world_size) if r % sequence_parallel_size == i]
        group = dist.new_group(ranks)
        if rank in ranks:
            _DATA_PARALLEL_GROUP = group


def get_sequence_parallel_group(backend: str = "nccl"):
    if backend == "nccl":
        return _SEQUENCE_PARALLEL_GROUP
    elif backend == "gloo":
        return _SEQUENCE_PARALLEL_GROUP_GLOO
    raise NotImplementedError(f"Unsupported backend: {backend}")


def get_sequence_parallel_world_size() -> int:
    grp = get_sequence_parallel_group()
    if grp is None:
        return 1
    try:
        return dist.get_world_size(group=grp)
    except Exception:
        return 1


def get_sequence_parallel_rank() -> int:
    grp = get_sequence_parallel_group()
    if grp is None:
        return 0
    try:
        return dist.get_rank(group=grp)
    except Exception:
        return 0


# ---------------------------------------------------------------------------
# all-to-all 通信原语（仿照 modeling_keye.py）
# ---------------------------------------------------------------------------

def _all_to_all_4d(input: torch.Tensor, scatter_idx: int, gather_idx: int, group) -> torch.Tensor:
    """4D all-to-all。

    支持两种方向：
      scatter_idx=2, gather_idx=1：(b, S/P, H,   d) -> (b, S,   H/P, d)   前向（seq->head）
      scatter_idx=1, gather_idx=2：(b, S,   H/P, d) -> (b, S/P, H,   d)   反向（head->seq）
    """
    P = dist.get_world_size(group)
    if P == 1:
        return input

    if scatter_idx == 2 and gather_idx == 1:
        # input: (b, S/P, H, d)
        b, shard_S, H, d = input.shape
        shard_H = H // P
        # (b, S/P, H, d) -> (b, S/P, P, H/P, d) -> (P, S/P, b, H/P, d)
        input_t = input.reshape(b, shard_S, P, shard_H, d).transpose(0, 2).contiguous()
        output = torch.empty_like(input_t)
        dist.all_to_all_single(output, input_t, group=group)
        # (P, S/P, b, H/P, d) -> (P*S/P, b, H/P, d) -> (b, S, H/P, d)
        output = output.reshape(P * shard_S, b, shard_H, d).transpose(0, 1).contiguous()
        return output  # (b, S, H/P, d)

    elif scatter_idx == 1 and gather_idx == 2:
        # input: (b, S, H/P, d)
        b, S, shard_H, d = input.shape
        shard_S = S // P
        # (b, S, H/P, d) -> (b, P, S/P, H/P, d) -> (H/P, P, S/P, b, d) -> (P, H/P, S/P, b, d)
        input_t = (
            input.reshape(b, P, shard_S, shard_H, d)
            .transpose(0, 3)
            .transpose(0, 1)
            .contiguous()
            .reshape(P, shard_H, shard_S, b, d)
        )
        output = torch.empty_like(input_t)
        dist.all_to_all_single(output, input_t, group=group)
        # (P, H/P, S/P, b, d) -> (P*H/P, S/P, b, d) -> (b, S/P, H, d)
        output = output.reshape(P * shard_H, shard_S, b, d).transpose(0, 2).contiguous()
        return output  # (b, S/P, H, d)
    else:
        raise RuntimeError("scatter_idx and gather_idx must be (2,1) or (1,2)")


class SeqAllToAll4D(torch.autograd.Function):
    """Autograd-aware 4D all-to-all，反向传播时交换 scatter/gather 方向。"""

    @staticmethod
    def forward(ctx, group, input: torch.Tensor, scatter_idx: int, gather_idx: int) -> torch.Tensor:
        ctx.group = group
        ctx.scatter_idx = scatter_idx
        ctx.gather_idx = gather_idx
        return _all_to_all_4d(input, scatter_idx, gather_idx, group=group)

    @staticmethod
    def backward(ctx, *grad_output: torch.Tensor) -> Tuple[None, torch.Tensor, None, None]:
        return (
            None,
            SeqAllToAll4D.apply(ctx.group, *grad_output, ctx.gather_idx, ctx.scatter_idx),
            None,
            None,
        )


# ---------------------------------------------------------------------------
# Halo exchange: 用于 causal conv1d 的边界交换
# rank r 需要 rank r-1 末尾 (kernel_size-1) 个 token 作为左边界上下文。
# rank 0 没有左邻居，用零填充（因果卷积本身在序列最左端也是用 0 填充）。
# ---------------------------------------------------------------------------

class ConvHaloExchange(torch.autograd.Function):
    """对 (B, C, S_local) 的张量做左侧 halo exchange。

    前向：每个 rank 把自己末尾 halo 个 token 发给右邻居，从左邻居收 halo 个 token 拼到前面。
          rank 0 的左侧用 0 填充。输出 shape: (B, C, halo + S_local)
    反向：按反向链路传梯度：
          - 来自 halo 区的梯度（前 halo 列）需要发回给左邻居，并加到左邻居输出 tensor 尾部的梯度上；
          - rank 0 的 halo 梯度直接丢弃（对应 0 填充）。
    """

    @staticmethod
    def forward(ctx, x: torch.Tensor, halo: int, group) -> torch.Tensor:
        ctx.halo = halo
        ctx.group = group

        if group is None or dist.get_world_size(group) == 1 or halo == 0:
            ctx.sp_size = 1
            ctx.sp_rank = 0
            # 单卡/无 SP：直接左侧 0 填充，保持接口一致
            if halo == 0:
                return x
            pad = x.new_zeros(x.shape[0], x.shape[1], halo)
            return torch.cat([pad, x], dim=-1)

        sp_size = dist.get_world_size(group)
        sp_rank = dist.get_rank(group)
        ctx.sp_size = sp_size
        ctx.sp_rank = sp_rank

        # dist.irecv/isend 的 src/dst 接受全局 rank，需要从组内 rank 转换
        def to_global(local_rank):
            return dist.get_global_rank(group, local_rank)

        B, C, S_local = x.shape
        # 取末尾 halo 个 token 准备发给右邻居
        send_right = x[:, :, -halo:].contiguous()
        # 接收缓冲：从左邻居收 halo 个 token
        recv_left = torch.zeros_like(send_right)

        # 用 isend/irecv 做点对点；rank 0 不收，最后一个 rank 不发
        reqs = []
        if sp_rank > 0:
            reqs.append(dist.irecv(recv_left, src=to_global(sp_rank - 1), group=group))
        if sp_rank < sp_size - 1:
            reqs.append(dist.isend(send_right, dst=to_global(sp_rank + 1), group=group))
        for r in reqs:
            r.wait()

        if sp_rank == 0:
            # rank 0 没有左邻居，halo 区用 0 填充
            recv_left = torch.zeros_like(send_right)

        return torch.cat([recv_left, x], dim=-1)

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor) -> Tuple[torch.Tensor, None, None]:
        halo = ctx.halo
        group = ctx.group
        sp_size = ctx.sp_size
        sp_rank = ctx.sp_rank

        if halo == 0:
            return grad_output, None, None

        # grad_output: (B, C, halo + S_local)
        grad_halo = grad_output[:, :, :halo].contiguous()   # 属于左邻居
        grad_local = grad_output[:, :, halo:].contiguous()  # 属于本 rank

        if sp_size == 1:
            # 单卡：halo 对应 0 填充，其梯度不需要传回
            return grad_local, None, None

        # dist.irecv/isend 的 src/dst 接受全局 rank
        def to_global(local_rank):
            return dist.get_global_rank(group, local_rank)

        # 反向通信：把 grad_halo 发给左邻居（它会加到自己输出尾部的梯度上）
        # 本 rank 从右邻居接收它发过来的 halo 梯度，加到 grad_local 尾部
        recv_right = torch.zeros_like(grad_halo)

        reqs = []
        if sp_rank < sp_size - 1:
            reqs.append(dist.irecv(recv_right, src=to_global(sp_rank + 1), group=group))
        if sp_rank > 0:
            reqs.append(dist.isend(grad_halo.contiguous(), dst=to_global(sp_rank - 1), group=group))
        for r in reqs:
            r.wait()

        if sp_rank < sp_size - 1:
            grad_local = grad_local.clone()
            grad_local[:, :, -halo:] = grad_local[:, :, -halo:] + recv_right

        return grad_local, None, None


class UlyssesLinearAttention(torch.nn.Module):
    """无参数的 Ulysses SP 包装，用于 GatedDeltaNet 线性 attention 核。"""

    def __init__(self) -> None:
        super().__init__()
        self.spg = get_sequence_parallel_group()

    def forward(
        self,
        chunk_fn,
        recurrent_fn,
        query: torch.Tensor,       # (b, S/P, H, d_k)
        key: torch.Tensor,         # (b, S/P, H, d_k)
        value: torch.Tensor,       # (b, S/P, H, d_v)
        z: torch.Tensor,           # (b, S/P, H, d_v)
        g: torch.Tensor,
        beta: torch.Tensor,
        use_precomputed_states: bool,
        recurrent_state,
        cache_params,
        cu_seqlens,
    ):
        sp_size = get_sequence_parallel_world_size()

        if sp_size > 1:
            # ── all2all #1：(b, S/P, H, d) → (b, S, H/P, d) ──────────────────
            query = _timed_all2all(self.spg, query, 2, 1, "linear/q #1")
            key   = _timed_all2all(self.spg, key,   2, 1, "linear/k #1")
            value = _timed_all2all(self.spg, value, 2, 1, "linear/v #1")
            z     = _timed_all2all(self.spg, z,     2, 1, "linear/z #1")
            # g, beta: (b, S/P, H) → (b, S, H/P)
            g    = _timed_all2all(self.spg, g.unsqueeze(-1),    2, 1, "linear/g #1").squeeze(-1)
            beta = _timed_all2all(self.spg, beta.unsqueeze(-1), 2, 1, "linear/beta #1").squeeze(-1)

        # ── attention core（完整 S，local H/P）──────────────────────────────
        # cu_seqlens 对应完整 S，和这里的 query/key/value 的 seq 维（完整 S）一致 ✓
        if not use_precomputed_states:
            core_out, last_state = chunk_fn(
                query, key, value,
                g=g, beta=beta,
                initial_state=None,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
                cu_seqlens=cu_seqlens,
            )
        else:
            core_out, last_state = recurrent_fn(
                query, key, value,
                g=g, beta=beta,
                initial_state=recurrent_state,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
            )

        if sp_size > 1:
            # ── all2all #2：(b, S, H/P, d) → (b, S/P, H, d) ──────────────────
            core_out = _timed_all2all(self.spg, core_out, 1, 2, "linear/out #2")
            z        = _timed_all2all(self.spg, z,        1, 2, "linear/z   #2")

        return core_out, z, last_state


class UlyssesFullAttention(torch.nn.Module):
    """无参数的 Ulysses SP 包装，用于 Qwen3_5Attention 全注意力核。"""

    def __init__(self) -> None:
        super().__init__()
        self.spg = get_sequence_parallel_group()

    def forward(
        self,
        attn_module,
        attention_interface,
        query_states: torch.Tensor,   # (b, H,    S/P, d)
        key_states: torch.Tensor,     # (b, H_kv, S/P, d)
        value_states: torch.Tensor,   # (b, H_kv, S/P, d)
        attention_mask,
        sp_size: int,
        **kwargs,
    ):
        # ── Sanity: SP 下 attention_mask 必须是 None ─────────────────────────
        # 经 all2all 后 seq 维变成完整 S，任何本地 S/P 形状的 4D mask 都会形状
        # 不匹配；packed/FA2 使用 cu_seqlens，其它情况依赖因果掩码（自动生成）。
        if sp_size > 1:
            assert attention_mask is None, (
                "[UlyssesFullAttention] attention_mask must be None under sequence "
                "parallel (sp_size>1). Use cu_seqlens for packed variable-length "
                "sequences or rely on the built-in causal mask."
            )

        if sp_size > 1:
            # q/k/v: (b, H, S/P, d) -> transpose -> (b, S/P, H, d)
            # all2all scatter head(dim=2), gather seq(dim=1)
            # -> (b, S, H/P, d) -> transpose -> (b, H/P, S, d)
            query_states  = _timed_all2all(self.spg, query_states.transpose(1, 2),  2, 1, "full/q #1").transpose(1, 2)
            key_states    = _timed_all2all(self.spg, key_states.transpose(1, 2),    2, 1, "full/k #1").transpose(1, 2)
            value_states  = _timed_all2all(self.spg, value_states.transpose(1, 2),  2, 1, "full/v #1").transpose(1, 2)

            # GQA num_key_value_groups 需要基于切分后的 head 数重新计算
            _orig_kvg = attn_module.num_key_value_groups
            local_num_q_heads  = attn_module.config.num_attention_heads  // sp_size
            local_num_kv_heads = attn_module.config.num_key_value_heads  // sp_size
            attn_module.num_key_value_groups = local_num_q_heads // local_num_kv_heads

        # ── attention core（完整 S，local H/P）──
        attn_output, attn_weights = attention_interface(
            attn_module,
            query_states,
            key_states,
            value_states,
            attention_mask,
            **kwargs,
        )
        # attn_output: (b, S, H/P, d)  —— flash_attn / sdpa 均以此格式返回

        if sp_size > 1:
            attn_module.num_key_value_groups = _orig_kvg  # 恢复

            # (b, S, H/P, d) --all2all scatter seq(dim=1), gather head(dim=2)--> (b, S/P, H, d)
            attn_output = _timed_all2all(self.spg, attn_output, 1, 2, "full/out #2")

        return attn_output, attn_weights


class AllGatherSeq(torch.autograd.Function):
    """seq 维度的 all-gather，反向为 scatter。"""

    @staticmethod
    def forward(ctx, input: torch.Tensor, group, gather_dim: int = 1) -> torch.Tensor:
        ctx.group = group
        ctx.gather_dim = gather_dim
        P = dist.get_world_size(group)
        if P == 1:
            return input
        parts = [torch.empty_like(input) for _ in range(P)]
        dist.all_gather(parts, input.contiguous(), group=group)
        return torch.cat(parts, dim=gather_dim)

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor) -> Tuple[torch.Tensor, None, None]:
        group = ctx.group
        gather_dim = ctx.gather_dim
        P = dist.get_world_size(group)
        rank = dist.get_rank(group)
        shard_size = grad_output.shape[gather_dim] // P
        slices = [slice(None)] * grad_output.dim()
        slices[gather_dim] = slice(rank * shard_size, (rank + 1) * shard_size)
        return grad_output[tuple(slices)].contiguous(), None, None


